import 'i18next';
import type common from '../../../public/locales/en/common.json';
import type home from '../../../public/locales/en/home.json';
import type invoices from '../../../public/locales/en/invoices.json';
import type masters from '../../../public/locales/en/masters.json';
import type search from '../../../public/locales/en/search.json';
import type uikit from '../../../public/locales/en/uikit.json';

/** Type-safe t() keys: each namespace's keys come from its English file (natural keys, generated by npm run i18n:build). */
declare module 'i18next' {
  interface CustomTypeOptions {
    defaultNS: 'common';
    keySeparator: false;
    nsSeparator: false;
    returnNull: false;
    resources: {
      common: typeof common;
      home: typeof home;
      invoices: typeof invoices;
      masters: typeof masters;
      search: typeof search;
      uikit: typeof uikit;
      phrases: Record<string, string>;
      patterns: Record<string, string>;
    };
  }
}
